import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.D7xI0JV8.js";const p=JSON.parse('{"title":"Developers","description":"","frontmatter":{},"headers":[],"relativePath":"developers.md","filePath":"developers.md"}'),o={name:"developers.md"};function d(s,e,n,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h1><p>This section is for builders who want to verify the system independently, integrate with the proof pipeline, or contribute to the codebase.</p><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><p><strong>Live backend showcase (every claim verified):</strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></p><p><strong>Source code:</strong><a href="https://github.com/obsqra-labs/zkdefi" target="_blank" rel="noreferrer">github.com/obsqra-labs/zkdefi</a></p><h3 id="primary-contracts-—-starknet-sepolia" tabindex="-1">Primary Contracts — Starknet Sepolia <a class="header-anchor" href="#primary-contracts-—-starknet-sepolia" aria-label="Permalink to &quot;Primary Contracts — Starknet Sepolia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Contract</th><th>Address</th></tr></thead><tbody><tr><td>ReputationRegistry</td><td><a href="https://sepolia.voyager.online/contract/0x10d00b33b5683afd776c58638a222aa10605d7eeafa95979b5246312b7e022" target="_blank" rel="noreferrer"><code>0x10d00b33b5683afd776c58638a222aa10605d7eeafa95979b5246312b7e022</code></a></td></tr><tr><td>FullPrivacyPoolV2</td><td><a href="https://sepolia.voyager.online/contract/0x03dde5617d362a6f9202cd3955b4508e2bd6b1c5d35250153beeb6237c811559" target="_blank" rel="noreferrer"><code>0x03dde5617d362a6f9202cd3955b4508e2bd6b1c5d35250153beeb6237c811559</code></a></td></tr><tr><td>VaultController (v3)</td><td><a href="https://sepolia.voyager.online/contract/0x2f29b985bc962f065160828296ab3889769a92a313d11077f186a81d0853b63" target="_blank" rel="noreferrer"><code>0x2f29b985bc962f065160828296ab3889769a92a313d11077f186a81d0853b63</code></a></td></tr><tr><td>ObsqraFactRegistry</td><td><a href="https://sepolia.voyager.online/contract/0x02009ab87f581a0a92f65906ce84664a5cfcb86f7266651f48a04fac3c62faa3" target="_blank" rel="noreferrer"><code>0x02009ab87f581a0a92f65906ce84664a5cfcb86f7266651f48a04fac3c62faa3</code></a></td></tr><tr><td>ZkmlVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923" target="_blank" rel="noreferrer"><code>0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923</code></a></td></tr></tbody></table><h3 id="primary-contracts-—-ethereum-sepolia" tabindex="-1">Primary Contracts — Ethereum Sepolia <a class="header-anchor" href="#primary-contracts-—-ethereum-sepolia" aria-label="Permalink to &quot;Primary Contracts — Ethereum Sepolia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Contract</th><th>Address</th></tr></thead><tbody><tr><td>Halo2Verifier (EZKL KZG)</td><td><a href="https://sepolia.etherscan.io/address/0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9" target="_blank" rel="noreferrer"><code>0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9</code></a></td></tr><tr><td>L1 EZKL Bridge Sender</td><td><a href="https://sepolia.etherscan.io/address/0x2a1b030f2835cB0ADC4ea271105e96da293853ab" target="_blank" rel="noreferrer"><code>0x2a1b030f2835cB0ADC4ea271105e96da293853ab</code></a></td></tr></tbody></table><h3 id="madara-l3" tabindex="-1">Madara L3 <a class="header-anchor" href="#madara-l3" aria-label="Permalink to &quot;Madara L3&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Contract</th><th>Address</th></tr></thead><tbody><tr><td>VerifiedFactRegistry</td><td><code>0x5ed322b12ddc28d27b7797d79516ca285137f9bab9fde870191119b4c68d691</code></td></tr></tbody></table><p>For the full contract map, see <a href="/docs/contracts">Deployed Contracts</a>.</p><h2 id="integration-orientations" tabindex="-1">Integration Orientations <a class="header-anchor" href="#integration-orientations" aria-label="Permalink to &quot;Integration Orientations&quot;">​</a></h2><h3 id="_1-user-facing-product-integrations" tabindex="-1">1) User-facing product integrations <a class="header-anchor" href="#_1-user-facing-product-integrations" aria-label="Permalink to &quot;1) User-facing product integrations&quot;">​</a></h3><p>Use deep links and route-state conventions to guide users into the correct operational surface.</p><h3 id="_2-backend-system-integrations" tabindex="-1">2) Backend/system integrations <a class="header-anchor" href="#_2-backend-system-integrations" aria-label="Permalink to &quot;2) Backend/system integrations&quot;">​</a></h3><p>Use endpoint-level APIs, enforce header discipline, and classify dependencies as production or experimental.</p><h3 id="_3-gate-aligned-ecosystem-integrations" tabindex="-1">3) GATE-aligned ecosystem integrations <a class="header-anchor" href="#_3-gate-aligned-ecosystem-integrations" aria-label="Permalink to &quot;3) GATE-aligned ecosystem integrations&quot;">​</a></h3><p>Use AEGIS/GATE semantics where relevant, but keep user UX grounded in current app and API behavior.</p><h2 id="system-shape" tabindex="-1">System Shape <a class="header-anchor" href="#system-shape" aria-label="Permalink to &quot;System Shape&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20UI%5BNext.js%20frontend%5D%20--%3E%20API%5BFastAPI%20backend%5D%0A%20%20API%20--%3E%20SN%5BStarknet%5D%0A%20%20API%20--%3E%20PX%5BProof%20%2B%20policy%20services%5D%0A%20%20API%20--%3E%20IDX%5BIndexers%20and%20market%20data%5D%0A%20%20SN%20--%3E%20UI">flowchart LR
  UI[Next.js frontend] --&gt; API[FastAPI backend]
  API --&gt; SN[Starknet]
  API --&gt; PX[Proof + policy services]
  API --&gt; IDX[Indexers and market data]
  SN --&gt; UI</pre><h2 id="practical-starting-points" tabindex="-1">Practical Starting Points <a class="header-anchor" href="#practical-starting-points" aria-label="Permalink to &quot;Practical Starting Points&quot;">​</a></h2><ul><li><a href="/docs/api-overview">API overview</a> for endpoint-level integration map</li><li><a href="/docs/architecture-summary">Architecture summary</a> for service boundaries</li><li><a href="/docs/contracts">Contracts</a> for deployed address references</li><li><a href="/docs/deploying-zkde-fi">Deploying zkde.fi</a> for serving model and docs pipeline</li><li><a href="/docs/aegis">AEGIS-1</a> for GATE standard framing</li></ul><h2 id="repository-references" tabindex="-1">Repository References <a class="header-anchor" href="#repository-references" aria-label="Permalink to &quot;Repository References&quot;">​</a></h2><ul><li>Setup: <a href="https://github.com/obsqra-labs/zkdefi/blob/main/docs/SETUP.md" target="_blank" rel="noreferrer">https://github.com/obsqra-labs/zkdefi/blob/main/docs/SETUP.md</a></li><li>Environment variables: <a href="https://github.com/obsqra-labs/zkdefi/blob/main/docs/ENV.md" target="_blank" rel="noreferrer">https://github.com/obsqra-labs/zkdefi/blob/main/docs/ENV.md</a></li><li>Architecture details: <a href="https://github.com/obsqra-labs/zkdefi/blob/main/docs/ARCHITECTURE.md" target="_blank" rel="noreferrer">https://github.com/obsqra-labs/zkdefi/blob/main/docs/ARCHITECTURE.md</a></li><li>Agent flow details: <a href="https://github.com/obsqra-labs/zkdefi/blob/main/docs/AGENT_FLOW.md" target="_blank" rel="noreferrer">https://github.com/obsqra-labs/zkdefi/blob/main/docs/AGENT_FLOW.md</a></li><li>Source repository: <a href="https://github.com/obsqra-labs/zkdefi" target="_blank" rel="noreferrer">https://github.com/obsqra-labs/zkdefi</a></li></ul><h2 id="production-vs-experimental-discipline" tabindex="-1">Production Vs Experimental Discipline <a class="header-anchor" href="#production-vs-experimental-discipline" aria-label="Permalink to &quot;Production Vs Experimental Discipline&quot;">​</a></h2><h3 id="problem-it-solves" tabindex="-1">Problem it solves <a class="header-anchor" href="#problem-it-solves" aria-label="Permalink to &quot;Problem it solves&quot;">​</a></h3><p>Teams often consume experimental endpoints as if they were stable contracts.</p><h3 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h3><p>This causes breakage during upgrades and avoidable incident response.</p><h3 id="guidance" tabindex="-1">Guidance <a class="header-anchor" href="#guidance" aria-label="Permalink to &quot;Guidance&quot;">​</a></h3><ul><li>Treat these route families as faster-changing surfaces: <ul><li><code>/api/v1/phase4a/status</code>, <code>/api/v1/phase4a/orchestrated/dashboard</code></li><li><code>/api/v1/vault-live/positions/{user_address}</code>, <code>/api/v1/vault-live/rebalance</code></li><li><code>/api/v1/zkdefi/sim/health</code>, <code>/api/v1/zkdefi/sim/state</code></li></ul></li><li>Version pin response expectations in your client code.</li><li>Keep fallback handling explicit for optional fields and async reconciliation states.</li></ul><h2 id="authentication-ground-rules" tabindex="-1">Authentication Ground Rules <a class="header-anchor" href="#authentication-ground-rules" aria-label="Permalink to &quot;Authentication Ground Rules&quot;">​</a></h2><p>For user-protected mutation flows, use <code>X-Wallet-Address</code> where required by endpoint policy. For admin-only routes, use <code>X-Admin-Key</code>. Do not assume all write routes are identically guarded; verify by endpoint and release.</p><h2 id="compliance-and-legal-boundary" tabindex="-1">Compliance And Legal Boundary <a class="header-anchor" href="#compliance-and-legal-boundary" aria-label="Permalink to &quot;Compliance And Legal Boundary&quot;">​</a></h2><p>This documentation is technical only. It does not provide legal, tax, or investment advice, and it does not guarantee that any generated disclosure artifact satisfies regulatory obligations in your jurisdiction.</p><p>Next: <a href="/docs/api-overview">API overview</a> | <a href="/docs/architecture-summary">Architecture summary</a> | <a href="/docs/deploying-zkde-fi">Deploying zkde.fi</a></p><h2 id="key-fixtures-verified-2026-03-05" tabindex="-1">Key Fixtures (Verified 2026-03-05) <a class="header-anchor" href="#key-fixtures-verified-2026-03-05" aria-label="Permalink to &quot;Key Fixtures (Verified 2026-03-05)&quot;">​</a></h2><ul><li><code>GET /api/v1/zkdefi/risk_profile/v2/{address}</code></li><li><code>GET /api/v1/zkdefi/risk_passport/v2/user/{address}</code></li><li><code>GET /api/v1/zkdefi/session_keys/list/{owner_address}</code></li><li><code>POST /api/v1/zkdefi/auth/session/start</code></li><li><code>POST /api/v1/zkdefi/lending/proof/credit-eligibility</code></li><li><code>POST /api/v1/zkdefi/zkml/scan</code></li></ul>`,39)])])}const f=a(o,[["render",d]]);export{p as __pageData,f as default};
